'use client';
import { useRef, useState } from 'react';
import { cx } from '../lib/cx';
import { Icon } from '../lib/icons';
import { Avatar, enter, Spin, Swap, Tip, useGrow } from '../lib/motion';
import { usePopover } from '../lib/popover';
import '../designme.css';
import './human-handoff.css';

export interface HandoffPerson {
  /** Used as the key, so keep it unique */
  name: string;
  initials?: string;
  /** The avatar's colour, like 'var(--dm-av-m)' */
  color?: string;
  /** Like "Billing" */
  team?: string;
  /** Whether they can take it now, like "Available", "In a call" or "Out until 2pm" */
  presence?: string;
  /** ok puts a green dot before the presence, warn turns it orange */
  tone?: 'ok' | 'warn';
}

export interface HandoffFact {
  label: string;
  value: string;
}

export interface HandoffStatus {
  /** wait is neutral with a spinner and the loader's sweep on its title; warn is a warning notice (a faint amber tint, the
      filled warning sign, and Reassign when there are `people`); ok is neutral with the person's avatar or a green tick */
  tone?: 'wait' | 'warn' | 'ok';
  title: string;
  detail?: string;
  /** Shown in place of the icon, like the person who just joined */
  person?: HandoffPerson;
}

export interface HumanHandoffProps {
  title?: string;
  /** Why the agent handed off, like "Refund over $500 needs a person" */
  reason: string;
  /** Who has it, or null while the agent is still finding someone */
  assignee: HandoffPerson | null;
  /** The two lines shown while assignee is null */
  finding?: { title: string; detail?: string };
  /** The people it can go to instead. Leave it out to hide Reassign */
  people?: HandoffPerson[];
  onReassign?: (person: HandoffPerson) => void;
  /** Seconds left until the reply is due. It shows whole minutes and turns orange under five; at 0 or less it reads overdue */
  secondsLeft: number;
  /** The whole window, for the bar and the line beside it ("15 min target") */
  targetSeconds?: number;
  /** What the person needs to pick it up */
  summary: string;
  /** A few key facts, as label and value rows */
  facts?: HandoffFact[];
  /** A link to the whole conversation */
  link?: { label: string; href?: string; onClick?: () => void; tip?: string };
  /** What the agent told the customer */
  message: string;
  /** The label over the message, like "Sent to Dana" */
  messageLabel?: string;
  /** Adds Edit: the message turns editable, and Save calls this with the new text */
  onMessageChange?: (text: string) => void;
  /** Adds "· edited" to the label */
  edited?: boolean;
  /** The row at the foot that says where it stands */
  status: HandoffStatus;
  labels?: { assignedTo?: string; context?: string; reassign?: string; reassignTo?: string; target?: string; edit?: string; save?: string; cancel?: string; edited?: string };
  className?: string;
}

/** The filled warning sign of a warning notice */
const WarnSign = () => (
  <svg className="dm-hox-wi" viewBox="0 0 24 24" aria-hidden="true"><path className="dm-a" d="M12 3.6 2.6 19.9h18.8z" /><path className="dm-b" d="M12 9.6v4.4M12 17v.01" /></svg>
);

const initialsOf = (p: HandoffPerson) => p.initials ?? p.name.split(' ').map(w => w[0]).join('').slice(0, 2);
const due = (s: number) => { const m = Math.floor(s / 60); return s <= 0 ? 'Reply overdue' : m < 1 ? 'Reply due in under a minute' : `Reply due in ${m} min`; };

/** The agent hands a conversation to a person: why, who has it (with Reassign), when the reply is due, the context they
    need to pick it up, and what the customer was told, with a row at the foot that says where it stands. */
export function HumanHandoff({
  title = 'Handed off to a person', reason, assignee, finding = { title: 'Finding someone' }, people, onReassign, secondsLeft, targetSeconds = 900,
  summary, facts = [], link, message, messageLabel = 'Sent to the customer', onMessageChange, edited, status, labels = {}, className
}: HumanHandoffProps) {
  const L = { assignedTo: 'Assigned to', context: 'Context passed along', reassign: 'Reassign', reassignTo: 'Reassign to', target: `${Math.round(targetSeconds / 60)} min target`,
    edit: 'Edit', save: 'Save', cancel: 'Cancel', edited: 'edited', ...labels };
  const menu = usePopover({ align: 'end', side: 'down' });
  // the warning notice's own Reassign opens the same list, upwards from the card's foot, over the card rather than below it
  const footMenu = usePopover({ align: 'end', side: 'up' });
  const [root, inner] = useGrow();
  const [editing, setEditing] = useState(false);
  // the message box is drawn afresh after each edit, so what React renders and what was typed never disagree
  const [rev, setRev] = useState(0);
  const box = useRef<HTMLDivElement>(null);
  const left = Math.max(0, secondsLeft);
  const tone = secondsLeft <= 0 ? 'dm-bad' : secondsLeft < 300 ? 'dm-warn' : '';

  const startEdit = () => {
    setEditing(true);
    requestAnimationFrame(() => { const b = box.current; if (!b) return; b.focus(); const s = getSelection(); s?.selectAllChildren(b); s?.collapseToEnd(); });
  };
  const save = () => { const t = box.current?.innerText.trim() ?? ''; if (t && t !== message) onMessageChange?.(t); setEditing(false); setRev(r => r + 1); };
  const cancel = () => { setEditing(false); setRev(r => r + 1); };
  const st = status.tone ?? 'wait';
  const link0 = link && (link.href
    ? <a className="dm-fchip dm-lnk dm-hox-lnk" href={link.href} onClick={link.onClick}><Icon name="link" size="xs" /><span>{link.label}</span></a>
    : <button type="button" className="dm-fchip dm-lnk dm-hox-lnk" onClick={link.onClick}><Icon name="link" size="xs" /><span>{link.label}</span></button>);

  return (
    <div data-dm="" className={className} style={{ width: '100%', containerType: 'inline-size' }}>
      <div ref={root} className="dm-hox dm-panel dm-growing">
      <div ref={inner} className="dm-grow">
        <div className="dm-hox-h">
          <span className="dm-hox-ic"><Icon name="user" /></span>
          <div className="dm-hox-ht"><b>{title}</b><span className="dm-muted">{reason}</span></div>
        </div>
        <div className="dm-hox-b">
          <div className="dm-hox-col">
            <span className="dm-hox-lb">{L.assignedTo}</span>
            <div className="dm-hox-who">
              <span className="dm-hox-av">{assignee ? <Avatar key={assignee.name} className="dm-enter" initials={initialsOf(assignee)} color={assignee.color ?? 'var(--dm-av-l)'} /> : <Spin />}</span>
              <span className="dm-hox-wt">
                <b><Swap>{assignee ? assignee.name : finding.title}</Swap></b>
                {assignee ? (
                  <span key={assignee.name + (assignee.presence ?? '')} className={cx('dm-hox-wd dm-enter', assignee.tone && 'dm-' + assignee.tone)}>
                    {assignee.presence && <span className="dm-dot" />}<span>{[assignee.team, assignee.presence].filter(Boolean).join(' · ')}</span>
                  </span>
                ) : <span className="dm-hox-wd"><span>{finding.detail}</span></span>}
              </span>
              {people && (
                <button type="button" className="dm-hox-rb" disabled={!assignee} {...menu.trigger}>{L.reassign}<Icon name="chev-d" size="xs" /></button>
              )}
            </div>
            <div className={cx('dm-hox-sla', tone)}>
              <div className="dm-hox-sl"><Icon name="clock" /><span className="dm-hox-sw"><span className="dm-hox-due dm-num">{due(secondsLeft)}</span><span className="dm-muted">{L.target}</span></span></div>
              <div className="dm-hox-bar" role="progressbar" aria-label="Time left to reply" aria-valuemin={0} aria-valuemax={targetSeconds} aria-valuenow={left}>
                <i style={{ width: `${Math.min(100, (left / targetSeconds) * 100)}%` }} />
              </div>
            </div>
            <div className="dm-hox-ms">
              <div className="dm-hox-mh">
                <span className="dm-hox-lb">{edited ? `${messageLabel} · ${L.edited}` : messageLabel}</span><span className="dm-sp" />
                {onMessageChange && editing && <button type="button" className="dm-pill dm-ghost dm-sm" onClick={cancel}>{L.cancel}</button>}
                {onMessageChange && (editing
                  ? <button type="button" className="dm-pill dm-primary dm-sm" onClick={save}>{L.save}</button>
                  : <button type="button" className="dm-pill dm-ghost dm-sm" onClick={startEdit}><Icon name="edit" size="xs" />{L.edit}</button>)}
              </div>
              <div key={rev} ref={box} className="dm-hox-mb" contentEditable={editing} suppressContentEditableWarning role="textbox" aria-multiline="true" aria-readonly={!editing}
                aria-label={messageLabel} spellCheck={false}>{message}</div>
            </div>
          </div>
          <div className="dm-hox-col">
            <span className="dm-hox-lb">{L.context}</span>
            <p className="dm-hox-sum">{summary}</p>
            {facts.length > 0 && (
              <div className="dm-hox-facts">
                {facts.map(f => <div key={f.label} className="dm-hox-f"><span className="dm-k">{f.label}</span><span className="dm-v dm-num">{f.value}</span></div>)}
              </div>
            )}
            {link0 && (link?.tip ? <Tip label={link.tip}>{link0}</Tip> : link0)}
          </div>
        </div>
        <div className={cx('dm-hox-st', st !== 'wait' && 'dm-' + st)} aria-live="polite">
          <div className="dm-hox-sr">
            <span className="dm-g">{status.person ? <Avatar initials={initialsOf(status.person)} color={status.person.color ?? 'var(--dm-av-l)'} />
              : st === 'wait' ? <Spin /> : st === 'warn' ? <WarnSign /> : <Icon name="ok" size="xs" />}</span>
            <span className="dm-t"><b><Swap className={st === 'wait' ? 'dm-shim' : undefined}>{status.title}</Swap></b>{status.detail && <span><Swap>{status.detail}</Swap></span>}</span>
            {st === 'warn' && people && assignee && (
              <button type="button" className={cx('dm-pill dm-warn dm-sm dm-hox-go', enter().className)} {...footMenu.trigger}>{L.reassign}</button>
            )}
          </div>
        </div>
        {people && [menu, footMenu].map((m, k) => (
          <div key={k} {...m.pop} className={cx(m.pop.className, 'dm-hox-pop')} role="menu" aria-label={L.reassignTo}>
            <div className="dm-ph">{L.reassignTo}</div>
            {people.map(p => (
              <button type="button" key={p.name} className="dm-mi" role="menuitemradio" aria-checked={p.name === assignee?.name}
                onClick={() => { if (p.name !== assignee?.name) onReassign?.(p); m.closeSoon(); }}>
                <Avatar initials={initialsOf(p)} color={p.color ?? 'var(--dm-av-l)'} />
                <span>{p.name}<span className="dm-d">{[p.team, p.presence].filter(Boolean).join(' · ')}</span></span>
                <span className="dm-ck"><Icon name="check" size="xs" /></span>
              </button>
            ))}
          </div>
        ))}
      </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Hand-off to a person ---------- */
/* the agent passes a conversation to a person: why, who has it (with Reassign), when the reply is due, what they need to
   pick it up, and what the customer was told, with a status line at the foot. The type and spacing are Draft review's; the
   two columns stack when narrow. Its content is 16px from every edge */
.dm-hox{position:relative;width:100%;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.dm-hox-h{display:flex;align-items:center;gap:var(--dm-s-3)}
.dm-hox-ic{width:32px;height:32px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);color:var(--dm-fg2);display:grid;place-items:center;flex:none}
.dm-hox-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-hox-ht b{font-weight:500;font-size:14px;line-height:20px}
.dm-hox-ht span{font-size:13px;line-height:18px}
.dm-hox-b{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:var(--dm-s-4) var(--dm-s-6);align-items:start;padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
@container (max-width:600px){.dm-hox-b{grid-template-columns:minmax(0,1fr)}.dm-hox-col+.dm-hox-col{padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}}
.dm-hox-col{display:flex;flex-direction:column;gap:var(--dm-s-2);min-width:0}
.dm-hox-lb{font-size:12px;color:var(--dm-muted)}
.dm-hox-who{display:flex;align-items:center;gap:var(--dm-s-3);min-height:40px}
.dm-hox-av{width:32px;height:32px;display:grid;place-items:center;flex:none;border-radius:50%;background:var(--dm-chip);color:var(--dm-fg2)}
/* the person's avatar is as big as the head's tile, so its words start where the title's do */
.dm-hox-av .dm-av{width:32px;height:32px;font-size:12px}
.dm-hox-wt{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-hox-wt b{font-weight:500;font-size:13.5px;line-height:20px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dm-hox-wd{display:flex;align-items:center;gap:6px;font-size:12px;line-height:18px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-hox-wd .dm-dot{color:var(--dm-faint)}
/* the person's status: the dot is a mark (--dm-ok-mark, --dm-warn-mark) and the words keep the text colours */
.dm-hox-wd.dm-ok .dm-dot{color:var(--dm-ok-mark)}
.dm-hox-wd.dm-warn{color:var(--dm-warn)}
.dm-hox-wd.dm-warn .dm-dot{color:var(--dm-warn-mark)}
/* Reassign: a small dropdown, like the one for how long in Permission gate. It is the row's last control, so its words end on
   the content's right edge (where the target time under it ends) and its hover box reaches 8px out round them */
.dm-hox-rb{display:inline-flex;align-items:center;gap:6px;height:28px;margin-right:calc(-1 * var(--dm-s-2));padding:0 var(--dm-s-2);border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);flex:none;transition:background .16s,color .16s}
.dm-hox-rb[aria-expanded="true"]{background:var(--dm-row);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.dm-hox-rb:hover{background:var(--dm-row);color:var(--dm-fg)}}
.dm-hox-rb>svg{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.dm-hox-rb[aria-expanded="true"]>svg{transform:rotate(180deg)}
.dm-hox-rb[disabled]{opacity:1;cursor:not-allowed;background:none;color:var(--dm-dis)}
.dm-hox-rb[disabled]>svg{color:var(--dm-dis)}
.dm-hox-pop{min-width:240px}
/* its menu opens out of the card, which keeps its height while the menu is open */
.dm-hox.dm-growing:has(.dm-hox-pop.dm-open){overflow:visible}
.dm-hox-pop .dm-mi .dm-av{width:20px;height:20px;font-size:9px}
.dm-hox-pop .dm-mi>span:not(.dm-ck):not(.dm-av){flex:1;min-width:0}
/* when the reply is due: the line counts down and the bar empties, amber in the last five minutes. The due time and the target
   are two sizes on one line, so they share a baseline in their own wrapper; the clock sits on the line's centre */
.dm-hox-sla{display:flex;flex-direction:column;gap:var(--dm-s-2);padding-top:var(--dm-s-2)}
.dm-hox-sl{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13px}
.dm-hox-sl>svg{color:var(--dm-fg2);flex:none}
.dm-hox-sw{flex:1;min-width:0;display:flex;align-items:baseline;gap:var(--dm-s-2)}
.dm-hox-sw .dm-muted{margin-left:auto;font-size:12px;white-space:nowrap}
.dm-hox-due{min-width:0}
.dm-hox-bar{height:4px;border-radius:2px;background:var(--dm-chip);overflow:hidden}
.dm-hox-bar i{display:block;height:100%;width:100%;border-radius:inherit;background:var(--dm-fg2);transition:width 1s linear,background .3s}
.dm-hox-sla.dm-warn .dm-hox-sl>svg,.dm-hox-sla.dm-warn .dm-hox-due{color:var(--dm-warn)}
.dm-hox-sla.dm-warn .dm-hox-bar i{background:var(--dm-warn-mark)}
.dm-hox-sla.dm-bad .dm-hox-sl>svg,.dm-hox-sla.dm-bad .dm-hox-due{color:var(--dm-bad)}
.dm-hox-sla.dm-bad .dm-hox-bar i{background:var(--dm-bad-mark)}
.dm-hox-sum{margin:0;font-size:13px;line-height:1.5;color:var(--dm-fg2)}
.dm-hox-facts{display:flex;flex-direction:column;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-hox-f{display:flex;align-items:center;gap:var(--dm-s-3);min-height:32px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13px}
.dm-hox-f .dm-k{width:72px;flex:none;color:var(--dm-muted)}
.dm-hox-f .dm-v{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dm-hox-lnk{align-self:flex-start;max-width:100%}
.dm-hox-lnk>span{overflow:hidden;text-overflow:ellipsis}
/* what the customer was told, editable in place. Edit is a ghost button, the row's last control, so its words end on the
   content's right edge (where the message box ends) */
.dm-hox-ms{display:flex;flex-direction:column;gap:var(--dm-s-2);margin-top:var(--dm-s-1);padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-hox-mh{display:flex;align-items:center;gap:var(--dm-s-2);min-height:28px}
.dm-hox-mh .dm-sp{flex:1}
.dm-hox-mh .dm-pill.dm-ghost:last-child{margin-right:-11px}
.dm-hox-mb{padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13.5px;line-height:1.5;outline:0;transition:box-shadow var(--dm-t-fast),background var(--dm-t-fast)}
.dm-hox-mb[contenteditable="true"]{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent)}
@supports (corner-shape:squircle){.dm-hox-mb[contenteditable="true"]{corner-shape:squircle;border-radius:var(--dm-r-box-sq)}}
.dm-hox-mb[contenteditable="true"]:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* where it stands: the card's footer, under a hairline, 16px from it and from the card's bottom edge. Its mark sits centred in
   the head's 32px tile column and its words start where the title's do. It is neutral while it waits (a spinner, the words
   with the loader's sweep), a warning notice when the person can't take it (owner, 18 Nov: a faint warning tint reaching 8px
   out round the row, the filled warning sign in --dm-warn-mark, the words in the text colours and Reassign, the action that
   settles it, as .pill.warn), and a neutral row with the person's avatar once they have it: no green fill (owner, 18 Nov) */
.dm-hox-st{margin-top:var(--dm-s-1);padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-hox-sr{display:grid;grid-template-columns:32px minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);min-height:28px;margin:calc(-1 * var(--dm-s-2));padding:var(--dm-s-2);border-radius:calc(var(--dm-r-card) - 8px);transition:background-color .32s var(--dm-ease)}
.dm-hox-st.dm-warn .dm-hox-sr{background:color-mix(in srgb,var(--dm-warn-bg) 45%,transparent)}
.dm-hox-sr .dm-g{width:32px;height:20px;display:grid;place-items:center;color:var(--dm-fg2)}
.dm-hox-sr .dm-g .dm-av{width:20px;height:20px;font-size:8.5px}
.dm-hox-st.dm-ok .dm-g{color:var(--dm-ok)}
:root[data-style="clean"] .dm-hox-st.dm-ok .dm-g,:root [data-style="clean"] .dm-hox-st.dm-ok .dm-g,:root [data-style="clean"].dm-hox-st.dm-ok .dm-g{color:var(--dm-ok-mark)}
.dm-hox-wi{width:16px;height:16px;overflow:visible}
.dm-hox-wi .dm-a{fill:var(--dm-warn-mark);stroke:var(--dm-warn-mark);stroke-width:2;stroke-linejoin:round}
.dm-hox-wi .dm-b{fill:none;stroke:var(--dm-surface);stroke-width:2.2;stroke-linecap:round}
.dm-hox-sr .dm-t{min-width:0;display:flex;flex-direction:column;font-size:13px;line-height:20px;color:var(--dm-fg)}
.dm-hox-sr .dm-t b{font-weight:500}
.dm-hox-sr .dm-t>span{font-size:12.5px;line-height:18px;color:var(--dm-muted)}
.dm-hox-st.dm-warn .dm-hox-sr .dm-t>span{color:var(--dm-fg2)}
.dm-hox-sr .dm-t,.dm-hox-sum,.dm-hox-mb,.dm-tmx-note>span{text-wrap:pretty}
/* on a phone the notice's Reassign goes under its words, starting where they start, so the words keep the row's width; the
   mark stays on the title's line */
@container (max-width:480px){.dm-hox-sr{grid-template-columns:32px minmax(0,1fr);align-items:start}.dm-hox-sr .dm-pill{grid-column:2;justify-self:start;margin-top:var(--dm-s-2)}}
/* Clean (owner, 17 and 18 Nov): the head's tile with a hairline, the footer an off-white foot strip whose words and Reassign
   sit 16px from its hairline and the card's bottom edge (--dm-strip-y) and 16px in from the sides; when the person can't take it
   the strip itself takes the faint warning tint. Reassign at the top is Clean's quiet select: the one hover, and the stronger
   fill while its menu is open */
:root[data-style="clean"] .dm-hox.dm-panel,:root [data-style="clean"] .dm-hox.dm-panel,:root [data-style="clean"].dm-hox.dm-panel{padding:16px 16px 0}
:root[data-style="clean"] .dm-hox-ic,:root [data-style="clean"] .dm-hox-ic,:root [data-style="clean"].dm-hox-ic{box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .dm-hox-ht b,:root [data-style="clean"] .dm-hox-ht b,:root [data-style="clean"].dm-hox-ht b{letter-spacing:-.01em}
:root[data-style="clean"] .dm-hox-rb,:root [data-style="clean"] .dm-hox-rb,:root [data-style="clean"].dm-hox-rb{color:var(--dm-fg2);transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
